INSERT INTO claim (claim_id, candidate_id, race_id, issue_id, text, bucket, attributed, derived_from, verdict, verification) VALUES
('demo-claim-boone-1-say', 'demo-cand-boone', 'demo-fl-governor', 'demo-fl-governor-issue-1', 'Gregory Boone says they will lower everyday costs by expanding the state''s fictional Homestead Relief Program and capping utility connection fees.', 'stated_position', true, NULL, NULL, 'single_source'),
('demo-claim-boone-1-done', 'demo-cand-boone', 'demo-fl-governor', 'demo-fl-governor-issue-1', 'Gregory Boone voted for the fictional 2024 Small Business Fee Reduction Act and served two terms on a county budget commission.', 'verifiable_fact', false, NULL, 'accurate', 'verified'),
('demo-claim-boone-1-check', 'demo-cand-boone', 'demo-fl-governor', 'demo-fl-governor-issue-1', 'Gregory Boone claimed the fictional relief program saved the average family $600 per year.', 'verifiable_fact', true, 'demo-claim-boone-1-say', 'accurate', 'verified'),
('demo-claim-boone-2-say', 'demo-cand-boone', 'demo-fl-governor', 'demo-fl-governor-issue-2', 'Gregory Boone pledges to raise starting teacher pay and expand the fictional Sunshine Apprenticeship Program to every county.', 'stated_position', true, NULL, NULL, 'single_source'),
('demo-claim-boone-2-done', 'demo-cand-boone', 'demo-fl-governor', 'demo-fl-governor-issue-2', 'Gregory Boone sponsored the fictional 2023 Classroom Supplies Grant and voted for the state''s teacher-pay increase that year.', 'verifiable_fact', false, NULL, 'accurate', 'verified'),
('demo-claim-boone-2-check', 'demo-cand-boone', 'demo-fl-governor', 'demo-fl-governor-issue-2', 'Gregory Boone claimed teacher vacancies fell 40% after the fictional apprenticeship pilot.', 'verifiable_fact', true, 'demo-claim-boone-2-say', 'mixed', 'verified'),
('demo-claim-boone-3-done', 'demo-cand-boone', 'demo-fl-governor', 'demo-fl-governor-issue-3', 'Gregory Boone co-sponsored the fictional 2022 Springs Restoration Bond and voted to fund septic-to-sewer conversions.', 'verifiable_fact', false, NULL, 'accurate', 'verified'),
('demo-claim-boone-3-check', 'demo-cand-boone', 'demo-fl-governor', 'demo-fl-governor-issue-3', 'Gregory Boone claimed water-quality violations dropped by half under the fictional compact.', 'verifiable_fact', true, NULL, 'mostly_accurate', 'verified'),
